        userId,
        referralBonus,
        'referral',
        'Monthly referral bonus',
        newResetDate, // Referral credits expire at next reset
        referralOperationId
      )
    }

    logger.info(
      {
        userId,
        freeOperationId,
        referralOperationId,
        freeGrantAmount,
        referralBonus,
        newResetDate,
        previousResetDate: currentResetDate,
      },
      'Processed monthly credit grants and reset'
    )

    return newResetDate
  })
}

