import { logger } from '../util/logger'
import { convertCreditsToUsdCents } from './credit-conversion'

/**
 * Determines the cost of one internal credit in USD cents for a given user.
 * TODO: Enhance this function to fetch user's plan and apply plan-specific rates.
 *
 * @param userId - The ID of the user (currently unused, for future enhancement).
 * @returns The cost of one internal credit in cents.
 */
export async function getUserCostPerCredit(
  userId: string | undefined
): Promise<number> {
  // Placeholder: Currently 1 cent per credit for all users. Can adjust in the future based on user
  return 1
}

// Re-export the pure conversion functions
export { convertCreditsToUsdCents, convertStripeGrantAmountToCredits } from './credit-conversion'

/**
 * Gets the cost per credit for a user. Currently hardcoded to 1 cent per credit,
 * but could be customized per user in the future.
 */
export async function getUserCostPerCredit(userId: string | undefined): Promise<number> {
  return 1 // 1 cent per credit
}

/**
 * Converts an internal credit system value to the equivalent monetary amount in USD cents,
 * based on the user's cost per credit.
 * Uses Math.ceil to ensure enough monetary value is calculated if rounding occurs.
 *
 * @param credits - The amount in internal credits.
 * @param centsPerCredit - The user's effective cost per internal credit (in cents).
 * @returns The equivalent amount in USD cents.
 */
export function convertCreditsToUsdCents(
  credits: number,
  centsPerCredit: number
): number {
  if (credits <= 0 || centsPerCredit <= 0) {
    return 0
  }
  // Total Cents = Credits * Cents per Credit
  const cents = credits * centsPerCredit
  // Use Math.ceil for safety, ensuring we calculate enough monetary value.
  return Math.ceil(cents)
}

/**
 * Converts a Stripe grant amount (in the smallest currency unit, e.g., cents for USD)
 * to the application's internal credit system units, based on the user's cost per credit.
 *
 * @param amountInSmallestUnit - The grant amount from Stripe, typically in cents.
 * @param centsPerCredit - The user's effective cost per internal credit (in cents).
 * @returns The equivalent amount in application credits. Uses Math.round for conversion.
 */
export function convertStripeGrantAmountToCredits(
  amountInSmallestUnit: number,
  centsPerCredit: number
): number {
  if (centsPerCredit <= 0) {
    return 0
  }
  // Credits = Total Cents / Cents per Credit
  const credits = amountInSmallestUnit / centsPerCredit
  // Use Math.round for robustness
  return Math.round(credits)
}

import { UsageLimits, PLAN_CONFIGS } from '../constants'
import { getPreviousFreeGrantAmount, calculateTotalReferralBonus } from './grant-credits'
import { logger } from '../util/logger'

/**
 * Determines the user's plan based on their Stripe Price ID.
 * Defaults to FREE if no matching price ID is found.
 * NOTE: Requires backend environment variables for Stripe Price IDs.
 */
export function getPlanFromPriceId(
  priceId: string | null | undefined,
  proPriceId?: string,
  moarProPriceId?: string
): UsageLimits {
  if (!priceId) {
    return UsageLimits.FREE
  }

  if (proPriceId && priceId === proPriceId) {
    return UsageLimits.PRO
  }
  if (moarProPriceId && priceId === moarProPriceId) {
    return UsageLimits.MOAR_PRO
  }

  return UsageLimits.FREE // Default to FREE for unknown or non-matching IDs
}

/**
 * Gets the total monthly credit grant amount for a given plan and user.
 * This includes both their plan's base credits and any referral bonuses,
 * combined into a single number.
 */
export async function getMonthlyGrantForPlan(
  plan: UsageLimits,
  userId?: string
): Promise<number> {
  // If no userId provided, just return the plan's base limit
  if (!userId) {
    return PLAN_CONFIGS[plan]?.limit ?? PLAN_CONFIGS[UsageLimits.FREE].limit
  }

  // Calculate total grant by adding base plan amount and referral bonuses
  const [freeGrantAmount, referralBonus] = await Promise.all([
    getPreviousFreeGrantAmount(userId),
    calculateTotalReferralBonus(userId),
  ])

  const totalGrant = freeGrantAmount + referralBonus
  logger.debug(
    { userId, plan, freeGrantAmount, referralBonus, totalGrant },
    'Calculated total monthly grant amount'
  )
  return totalGrant
}

import { UsageLimits } from '../constants'

export interface InvoiceLineItem {
  amount: number
